#!/usr/bin/env python3
"""Generate ccl_science_data/gen_reader_ext.py from Rust source files for LSP visibility."""
import argparse
import re
from pathlib import Path

NS_REX = re.compile(r'impl NamespacedEntity for (.*) { const NS: & str = "(.*)"; }')

HEADER = """\
# AUTO-GENERATED by scripts/gen_reader.py — do not edit manually.
# Run `make gen-reader` to regenerate.

import numpy as np

from .common import GenReader, get_arr


"""


def _parse_entities(
    gen_txt: str,
) -> tuple[list[tuple[str, str, str]], list[tuple[str, str, str]], dict[str, str]]:
    numents: list[tuple[str, str, str]] = []  # (dtn, en, ns)
    arrents: list[tuple[str, str, str]] = []  # (dtn, en, ns)
    sdtmap: dict[str, str] = {}

    for class_name, ns in NS_REX.findall(gen_txt):
        for dtn, en in re.findall(
            rf'impl Entity for {class_name} {{ type T = u(\d+); const N: usize = \d+; const NAME: & str = "(.*)"; }}',
            gen_txt,
        ):
            numents.append((dtn, en, ns))

        for dtn, en in re.findall(
            rf'impl Entity for {class_name} {{ type T = Box<\[u(\d+)\]>; const N: usize = \d+; const NAME: & str = "(.*)"; }}',
            gen_txt,
        ):
            arrents.append((dtn, en, ns))
            sdtmap[en] = re.findall(
                rf"impl VariableSizeAttribute for {class_name} {{ type SizeType = u(\d+); type LocType = .*; }}",
                gen_txt,
            )[0]

    return numents, arrents, sdtmap


def generate(gen_root: Path, out_path: Path) -> None:
    gen_txt = "\n\n".join(
        fp.read_text() for fp in (gen_root / "rankless_rs/src/gen/").iterdir()
    )
    numents, arrents, sdtmap = _parse_entities(gen_txt)

    lines: list[str] = ["class GenReaderExt(GenReader):"]

    if not numents and not arrents:
        lines.append("    pass")

    for dtn, en, ns in numents:
        enr = en.replace("-", "_")
        lines.append(f'    def load_arr_{enr}(self) -> np.ndarray:')
        lines.append(f'        return get_arr("{ns}/{en}", {dtn})')
        lines.append("")

    for dtn, en, ns in arrents:
        enr = en.replace("-", "_")
        sdt = sdtmap[en]
        lines.append(f'    def load_varr_{enr}_targets(self) -> np.ndarray:')
        lines.append(f'        return get_arr("{ns}/{en}/targets", {dtn})')
        lines.append("")
        lines.append(f'    def load_varr_{enr}_sizes(self) -> np.ndarray:')
        lines.append(f'        return get_arr("{ns}/{en}/sizes", {sdt})')
        lines.append("")

    out_path.write_text(HEADER + "\n".join(lines) + "\n")
    total = len(numents) + 2 * len(arrents)
    print(f"Generated {total} methods → {out_path}")


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate GenReaderExt with explicit methods from Rust gen files"
    )
    parser.add_argument("--gen-root", default=".", help="Path to rankless project root")
    parser.add_argument(
        "--out",
        default="ccl_science_data/gen_reader_ext.py",
        help="Output Python file",
    )
    args = parser.parse_args()
    generate(Path(args.gen_root), Path(args.out))


if __name__ == "__main__":
    main()
